/* Enforce hidden attribute utility */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1c1a27;
  --color-card: #2c273e;
  --color-accent: #f7b731;
  --color-text: #f0f0f5;
  --color-muted: #8b85a3;
  --color-border: #0e0d15;
  --color-error: #fc5c65;
  --color-highlight: #453e5d;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  /* Pixel grid pattern */
  background-image:
    linear-gradient(to right, rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 16px 16px;
  color: var(--color-text);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.converter-card {
  background-color: var(--color-card);
  width: 100%;
  max-width: 460px;
  padding: 2rem;
  /* Pixelated chunky border using box-shadows */
  border: 4px solid var(--color-border);
  box-shadow:
    6px 6px 0px 0px var(--color-border),
    inset -3px -3px 0px 0px #1f1b2d,
    inset 3px 3px 0px 0px #3d3655;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.converter-header {
  text-align: center;
}

.pixel-icon {
  font-size: 2.25rem;
  line-height: 1;
  margin-bottom: 0.5rem;
}

.converter-title {
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-transform: uppercase;
  text-shadow: 2px 2px 0px var(--color-border);
}

.converter-subtitle {
  font-size: 0.825rem;
  color: var(--color-muted);
  margin-top: 0.25rem;
  letter-spacing: 1px;
}

.converter-body {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.field-label {
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--color-text);
}

.input-wrapper {
  position: relative;
}

.pixel-input {
  width: 100%;
  padding: 0.75rem 1rem;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: inherit;
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  border: 3px solid var(--color-border);
  outline: none;
  box-shadow: inset 3px 3px 0px 0px rgba(0, 0, 0, 0.4);
  transition: border-color 0.15s ease, background-color 0.15s ease;
}

.text-uppercase {
  text-transform: uppercase;
}

.pixel-input:hover {
  background-color: #232031;
}

.pixel-input:focus {
  border-color: var(--color-accent);
  background-color: #232031;
  box-shadow:
    inset 3px 3px 0px 0px rgba(0, 0, 0, 0.4),
    0 0 0 2px var(--color-accent);
}

.pixel-input::placeholder {
  color: var(--color-muted);
  font-weight: normal;
}

/* Hide standard number stepper buttons */
.pixel-input::-webkit-outer-spin-button,
.pixel-input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
.pixel-input[type="number"] {
  appearance: textfield;
  -moz-appearance: textfield;
}

.result-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.65rem 0.85rem;
  background: var(--color-highlight);
  border: 2px dashed var(--color-border);
  min-height: 44px;
}

.result-tag {
  font-size: 0.75rem;
  font-weight: bold;
  letter-spacing: 1px;
  color: var(--color-muted);
}

.result-text {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 2px;
  word-break: break-all;
  text-align: right;
  color: var(--color-accent);
}

.result-text.error {
  color: var(--color-error);
  letter-spacing: 1px;
}

.pixel-divider {
  height: 4px;
  background-color: var(--color-border);
  margin: 0.25rem 0;
}

.converter-footer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  margin-top: 0.5rem;
}

.pixel-btn {
  width: 100%;
  padding: 0.75rem 1rem;
  background-color: var(--color-accent);
  color: var(--color-border);
  font-family: inherit;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 1.5px;
  border: 3px solid var(--color-border);
  cursor: pointer;
  box-shadow: 4px 4px 0px 0px var(--color-border);
  transition: transform 0.05s, box-shadow 0.05s, background-color 0.15s;
}

.pixel-btn:hover {
  background-color: #ffd166;
}

.pixel-btn:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px 0px var(--color-border);
}

.helper-text {
  font-size: 0.75rem;
  color: var(--color-muted);
  text-align: center;
}

@media (max-width: 400px) {
  body {
    padding: 0.5rem;
  }
  .converter-card {
    padding: 1.25rem;
  }
  .converter-title {
    font-size: 1.15rem;
  }
  .pixel-input {
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  const ROMAN_MAP = [
    { value: 1000, numeral: 'M' },
    { value: 900, numeral: 'CM' },
    { value: 500, numeral: 'D' },
    { value: 400, numeral: 'CD' },
    { value: 100, numeral: 'C' },
    { value: 90, numeral: 'XC' },
    { value: 50, numeral: 'L' },
    { value: 40, numeral: 'XL' },
    { value: 10, numeral: 'X' },
    { value: 9, numeral: 'IX' },
    { value: 5, numeral: 'V' },
    { value: 4, numeral: 'IV' },
    { value: 1, numeral: 'I' }
  ];

  // Strict standard Roman numeral regex matching 1 to 3999
  const STRICT_ROMAN_REGEX = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

  const ROMAN_CHAR_VALUES = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
  };

  function intToRoman(num) {
    if (typeof num !== 'number' || isNaN(num) || num < 1 || num > 3999) {
      return null;
    }
    let result = '';
    let remaining = Math.floor(num);
    for (let i = 0; i < ROMAN_MAP.length; i++) {
      while (remaining >= ROMAN_MAP[i].value) {
        result += ROMAN_MAP[i].numeral;
        remaining -= ROMAN_MAP[i].value;
      }
    }
    return result;
  }

  function romanToInt(romanStr) {
    const str = romanStr.trim().toUpperCase();
    if (!str || !STRICT_ROMAN_REGEX.test(str)) {
      return null;
    }

    let total = 0;
    for (let i = 0; i < str.length; i++) {
      const current = ROMAN_CHAR_VALUES[str[i]];
      const next = ROMAN_CHAR_VALUES[str[i + 1]];

      if (next && current < next) {
        total += (next - current);
        i++;
      } else {
        total += current;
      }
    }

    if (total < 1 || total > 3999) {
      return null;
    }

    // Canonical reversibility double-check
    if (intToRoman(total) !== str) {
      return null;
    }

    return total;
  }

  document.addEventListener('DOMContentLoaded', function () {
    const numberInput = document.getElementById('number-input');
    const numberResult = document.getElementById('number-result');
    const romanInput = document.getElementById('roman-input');
    const romanResult = document.getElementById('roman-result');
    const clearBtn = document.getElementById('clear-btn');

    function updateNumberToRoman() {
      const rawVal = numberInput.value.trim();
      if (!rawVal) {
        numberResult.textContent = '—';
        numberResult.classList.remove('error');
        return;
      }

      const num = Number(rawVal);
      // Ensure whole integer within [1, 3999]
      if (!Number.isInteger(num) || num < 1 || num > 3999) {
        numberResult.textContent = 'Not valid';
        numberResult.classList.add('error');
      } else {
        const roman = intToRoman(num);
        numberResult.textContent = roman || 'Not valid';
        numberResult.classList.toggle('error', !roman);
      }
    }

    function updateRomanToNumber() {
      const rawVal = romanInput.value.trim();
      if (!rawVal) {
        romanResult.textContent = '—';
        romanResult.classList.remove('error');
        return;
      }

      const parsed = romanToInt(rawVal);
      if (parsed === null) {
        romanResult.textContent = 'Not valid';
        romanResult.classList.add('error');
      } else {
        romanResult.textContent = parsed.toString();
        romanResult.classList.remove('error');
      }
    }

    numberInput.addEventListener('input', updateNumberToRoman);
    romanInput.addEventListener('input', updateRomanToNumber);

    clearBtn.addEventListener('click', function () {
      numberInput.value = '';
      romanInput.value = '';
      updateNumberToRoman();
      updateRomanToNumber();
      numberInput.focus();
    });
  });
})();
